import { Fragment } from "react";
import { capsWidth, cn, giantSize } from "@/lib/utils";

/** Small label above a heading, e.g. “Latest”. */
export function Label({ children, className }: { children: React.ReactNode; className?: string }) {
  return <p className={cn("text-base text-ink", className)}>{children}</p>;
}

/** Left-aligned section heading: label + two-line medium heading. */
export function SectionHeading({
  label,
  heading,
  text,
  as: Tag = "h2",
  className,
}: {
  label?: string | null;
  heading?: string | null;
  text?: string | null;
  as?: "h1" | "h2";
  className?: string;
}) {
  if (!label && !heading && !text) return null;
  return (
    <div className={cn("px-gutter", className)}>
      {label && <Label className="mb-[clamp(16px,calc(1.24vw+11.4px),35px)]">{label}</Label>}
      {heading && <Tag className="max-w-[13.5ch] text-h2 font-medium text-balance">{heading}</Tag>}
      {text && <p className="mt-5 max-w-[46ch] text-lead text-ink-2">{text}</p>}
    </div>
  );
}

/**
 * Index range of the words to show in the brand gradient: the given accent
 * word or phrase (matched ignoring case and punctuation, last occurrence),
 * or the last word when there is none or it isn't in the text.
 */
export function accentRange(words: string[], accent?: string | null): [number, number] {
  const norm = (w: string) => w.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
  const target = (accent ?? "").trim().split(/\s+/).map(norm).filter(Boolean);
  if (target.length) {
    for (let i = words.length - target.length; i >= 0; i--) {
      if (target.every((t, j) => norm(words[i + j]) === t)) return [i, i + target.length - 1];
    }
  }
  return [words.length - 1, words.length - 1];
}

/**
 * Display text with one accent word (or short phrase) marked up on its own.
 * It used to carry the brand gradient; it is now plain ink like the rest.
 */
export function AccentText({ text, accent, phrases = false }: { text: string; accent?: string | null; phrases?: boolean }) {
  const words = text.trim().split(/\s+/);
  // Giant titles: the last two words stay together when they are no wider than the longest word, so no browser
  // leaves one word alone on the last line (Safari wraps these plainly; see `.giant-wrap` in globals.css). The
  // title's size comes from its longest word (giantSize), so the pair always fits.
  if (phrases && words.length > 2 && !/[,.;:!?\u2013\u2014]$/.test(words[words.length - 2])) {
    const pair = `${words[words.length - 2]} ${words[words.length - 1]}`;
    if (capsWidth(pair) <= Math.max(...words.map((w) => capsWidth(w)))) words.splice(-2, 2, pair.replace(" ", "\u00a0"));
  }
  const [start, end] = accentRange(words, accent);
  // Words from `from` to `to`, with the accent words among them marked up.
  const run = (from: number, to: number) => {
    const a = Math.max(start, from), b = Math.min(end, to);
    if (a > b) return words.slice(from, to + 1).join(" ");
    const before = words.slice(from, a).join(" ");
    const after = words.slice(b + 1, to + 1).join(" ");
    return (
      <>
        {before && `${before} `}
        <span className="text-gradient">{words.slice(a, b + 1).join(" ")}</span>
        {after && ` ${after}`}
      </>
    );
  };
  // Phrases: each part up to a comma, full stop or dash is kept together, so a line breaks between phrases
  // first ("EVERYTHING DIGITAL, / DONE FOR YOU.", never "DIGITAL, DONE FOR / YOU."). A phrase too long for
  // one line still wraps inside itself.
  const groups: [number, number][] = [];
  if (phrases) {
    let from = 0;
    words.forEach((w, i) => {
      if (i === words.length - 1 || /[,.;:!?\u2013\u2014]$/.test(w)) {
        groups.push([from, i]);
        from = i + 1;
      }
    });
  }
  if (groups.length < 2) return run(0, words.length - 1);
  return (
    <>
      {groups.map(([from, to], i) => (
        <Fragment key={from}>
          {i > 0 && " "}
          <span className="phrase inline-block">{run(from, to)}</span>
        </Fragment>
      ))}
    </>
  );
}

/**
 * The design system's line-mask reveal: the text rises into view from behind
 * a mask as it scrolls in (see Reveal.tsx and globals.css).
 */
export function MaskReveal({ children }: { children: React.ReactNode }) {
  return (
    <span data-reveal-mask className="reveal-mask">
      <span>{children}</span>
    </span>
  );
}

/** Centered giant uppercase heading used by heroes and the big section titles. */
export function GiantHeading({
  label,
  heading,
  accent,
  text,
  as: Tag = "h2",
  labelStyle = "plain",
  roomy = false,
  className,
  children,
}: {
  label?: string | null;
  heading: string;
  /** Word or short phrase shown in the brand gradient; defaults to the last word. */
  accent?: string | null;
  text?: string | null;
  as?: "h1" | "h2" | "p";
  labelStyle?: "plain" | "pill";
  /**
   * Phones: line-height 1 instead of 0.92, for a title where a comma ends a line above a wider one
   * and would almost touch its capitals (Services). Others keep the tight lines (Lucky liked Home's).
   */
  roomy?: boolean;
  className?: string;
  children?: React.ReactNode;
}) {
  const title = (
    <MaskReveal>
      <AccentText text={heading} accent={accent} phrases />
    </MaskReveal>
  );
  const size = giantSize(heading);
  return (
    <div className={cn("@container flex flex-col items-center px-gutter text-center", className)}>
      {label &&
        (labelStyle === "pill" ? (
          <p className="mb-[clamp(24px,calc(2.03vw+16.4px),55px)] rounded-[4px] border border-ink/25 px-[0.6em] py-[0.15em] text-base text-ink">
            {label}
          </p>
        ) : (
          <Label className="mb-[clamp(20px,calc(2.29vw+11.4px),55px)]">{label}</Label>
        ))}
      {/* Whole words only: words wrap between each other, never inside (see giantSize), and between
          phrases first (AccentText). Phones wrap plainly; from tablets up the lines are balanced, except
          in Safari, whose balancing squeezes them into extra lines (see `.giant-wrap` in globals.css). */}
      <Tag className={cn(size.className, "giant-wrap w-full font-bold uppercase", roomy && "max-sm:leading-none")} style={size.style}>
        {title}
      </Tag>
      {text && (
        <p className="mt-[clamp(20px,calc(1.64vw+13.8px),45px)] max-w-[34ch] text-lead text-ink text-balance">{text}</p>
      )}
      {children}
    </div>
  );
}
